package dev.eugheist.ttmodern;
/** Actual client use/release packets with server damage, isolated from armor/effect reductions. */
final class SwordBlockingWorldAudit {
 static boolean saved,checked,useKey,gravity,flying;static net.minecraft.world.phys.Vec3 position;static float yaw,pitch;static int hearts;static float health,absorption;
 static net.minecraft.world.item.ItemStack held;static net.minecraft.world.level.GameType mode;
 static java.util.List<net.minecraft.world.item.ItemStack> armor;
 static java.util.List<net.minecraft.world.effect.MobEffectInstance> effects;
 static net.minecraft.world.Difficulty difficulty;
 static void restore(net.minecraft.client.Minecraft mc){if(!saved)return;mc.options.keyUse.setDown(useKey);var server=mc.getSingleplayerServer();var p=server.getPlayerList().getPlayer(mc.player.getUUID());p.stopUsingItem();p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,held);for(int i=0;i<4;i++)p.getInventory().armor.set(i,armor.get(i));p.removeAllEffects();for(var effect:effects)p.addEffect(effect);SoulHearts.set(p,hearts);SoulHearts.sync(p);p.setGameMode(mode);p.setNoGravity(gravity);p.getAbilities().flying=flying;p.onUpdateAbilities();p.teleportTo(position.x,position.y,position.z);p.setYRot(yaw);p.setXRot(pitch);p.setHealth(health);p.setAbsorptionAmount(absorption);p.invulnerableTime=0;p.inventoryMenu.broadcastChanges();server.setDifficulty(difficulty,true);saved=false;}
 static void tick(net.minecraft.client.Minecraft mc,int t){
  if(t==2080){useKey=mc.options.keyUse.isDown();mc.getSingleplayerServer().submit(()->{var server=mc.getSingleplayerServer();var p=server.getPlayerList().getPlayer(mc.player.getUUID());held=p.getMainHandItem().copy();gravity=p.isNoGravity();flying=p.getAbilities().flying;position=p.position();yaw=p.getYRot();pitch=p.getXRot();mode=p.gameMode.getGameModeForPlayer();hearts=SoulHearts.get(p);health=p.getHealth();absorption=p.getAbsorptionAmount();armor=p.getInventory().armor.stream().map(net.minecraft.world.item.ItemStack::copy).toList();effects=p.getActiveEffects().stream().map(net.minecraft.world.effect.MobEffectInstance::new).toList();difficulty=server.getWorldData().getDifficulty();saved=true;server.setDifficulty(net.minecraft.world.Difficulty.NORMAL,true);p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.setNoGravity(true);p.removeAllEffects();for(int i=0;i<4;i++)p.getInventory().armor.set(i,net.minecraft.world.item.ItemStack.EMPTY);SoulHearts.set(p,0);SoulHearts.sync(p);p.setHealth(20);p.setAbsorptionAmount(0);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.item.ItemStack(AwakenedSword.ITEM.get()));p.inventoryMenu.broadcastChanges();}).join();}
  if(t==2100){EnchanterClientAudit.check(mc.player.getMainHandItem().is(AwakenedSword.ITEM.get()),"blocking sword inventory sync");mc.options.keyUse.setDown(true);mc.gameMode.useItem(mc.player,net.minecraft.world.InteractionHand.MAIN_HAND);}
  if(t==2120){EnchanterClientAudit.check(mc.player.isUsingItem()&&mc.player.getUseItem().getUseAnimation()==net.minecraft.world.item.UseAnim.BLOCK,"native client blocking animation after use packet");mc.getSingleplayerServer().submit(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());EnchanterClientAudit.check(p.isUsingItem(),"native server received sword use packet");var cow=net.minecraft.world.entity.EntityType.COW.create(p.serverLevel());cow.setPos(p.getX(),p.getY(),p.getZ()+2);p.invulnerableTime=0;EnchanterClientAudit.check(p.hurt(p.damageSources().mobAttack(cow),8)&&p.getHealth()==15.5f,"actual blocked8damage becomes4.5health damage");}).join();}
  if(t==2130){EnchanterClientAudit.check(mc.player.getHealth()==15.5f,"blocked health synchronizes to client");mc.options.keyUse.setDown(false);mc.gameMode.releaseUsingItem(mc.player);}
  if(t==2140){mc.getSingleplayerServer().submit(()->{try{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());EnchanterClientAudit.check(!p.isUsingItem(),"actual release packet ends sword block");checked=true;System.out.println("TT SWORD BLOCK WORLD CLIENT AUDIT: ALL PASS (actual use/release packets,client BLOCK animation,server4.5damage from8,health sync,restored inventory/effects/health/difficulty)");}finally{restore(mc);}}).join();}
 }
}
